/* engines/peaks.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  async function createPeaks(url, startAt, autoplay) {
    try { await P.loadPeaksScript(); } catch {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    if (!window.peaks) return false;

    const audioContext = P.sharedAudioContext();
    if (!audioContext) {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }

    P.showWaveMode();
    const surface = document.createElement("div");
    surface.style.width = "100%";
    surface.style.height = "100%";
    P.waveform.appendChild(surface);

    const colors = P.waveformColors();
    P.audio.src = url;
    P.audio.load();

    P.peaks = window.peaks.init({
      mediaElement: P.audio,
      mediaUrl: url,
      webAudio: { audioContext: P.audioContext },
      zoomview: {
        container: surface,
        waveformColor: colors.waveColor,
        playedWaveformColor: colors.progressColor,
        playheadColor: colors.cursorColor,
        showAxisLabels: false,
        enablePoints: false,
        enableSegments: false,
      },
    }, (error) => {
      if (error) {
        P.fallbackToHtml5();
        P.notify("engine");
        return;
      }
      P.finishLoading();
      if (startAt) P.setTime(startAt);
      if (autoplay) P.attemptPlay();
    });
    return true;
  }
  Object.assign(P, { createPeaks });
}
